import{z as s,x as l,o as E,c as B,q as i,j as o,D as A,d as e,s as n,S as p,b as t}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"SARP 与 GARP","description":"","frontmatter":{"title":"SARP 与 GARP","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/sarp-garp.md","filePath":"econ/sarp-garp.md","lastUpdated":1791413859000}'),P={name:"econ/sarp-garp.md"};function R(d,a,x,f,c,m){const r=l("Mermaid");return E(),B("div",null,[a[2]||(a[2]=i('<h1 id="sarp-与-garp" tabindex="-1">SARP 与 GARP <a class="header-anchor" href="#sarp-与-garp" aria-label="Permalink to &quot;SARP 与 GARP&quot;">​</a></h1><div class="epigraph"><p>成对不循环还不够。要把整条显示偏好链收成一个效用，需要强公理或广义公理，以及 Afriat 不等式。</p><footer>—— 据 Afriat, The construction of utility functions from expenditure data, 1967；Varian, The nonparametric approach to demand analysis, Econometrica, 1982 整理</footer></div><p>上一课<a href="/econ/revealed-preference">显示偏好 WARP</a>钉死了成对一致性：选了 \\(x^t\\) 时 \\(x^s\\) 买得起却没选，就不能在另一期反过来。本课不重画两条预算互相吞掉的图，也不再定义 \\(R^D\\)。缺口是：WARP 不够循环一致性。三条以上的链可以成环，成对却都通过；要恢复一个完整的理性偏好，需要 SARP / GARP，以及 Afriat 的可计算版本。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>直接显示 \\(x^t\\,R^D\\,x^s\\)：当期选 \\(x^t\\) 且 \\(p^t\\cdot x^s\\le p^t\\cdot x^t\\)。WARP 禁止 \\(x^t\\,R^D\\,x^s\\,R^D\\,x^t\\) 且二者不等。三个观测可以 \\(x^1\\,R^D\\,x^2\\,R^D\\,x^3\\,R^D\\,x^1\\)，两两检查都不触发 WARP。钱泵在链上，不在成对上。缺口是把传递闭包管起来。</p><p><span class="marginnote">传递闭包翻译成大白话：不只看「直接比过」的成对关系，还要把顺着箭头能一路走到的都连起来。A 优于 B、B 优于 C，即使 A 没和 C 同台比过，也记作 A（间接）优于 C。GARP 检查的正是这张加长后的图里有没有绕回起点的圈。</span></p><p><span class="marginnote">直觉类比：钱泵像倒卖门票的中间商。若你觉得 x1 优于 x2、x2 优于 x3、x3 又优于 x1，中间商就能跟你从 x3 换到 x1（每次让你贴点钱）、再换 x2、再换回 x3，转一圈他的口袋鼓了，你的钱少了。循环偏好是一台自动抽钱机。</span></p><p>强公理 SARP：间接显示偏好 \\(R\\)（\\(R^D\\) 的传递闭包）无循环——若 \\(x^1 R x^k\\) 且诸束不全相等，则不能 \\(x^k R^D x^1\\)。广义公理 GARP（Varian, 1982）：若 \\(x R y\\)，则不能 \\(p_y\\cdot x\\lt p_y\\cdot y\\)。GARP 允许无差异造成的「平的」集值需求；SARP 更适合单值需求。有限观测上，GARP 才是「存在凹效用合理化」的恰条件。</p><h3 id="afriat-把公理收成线性不等式" tabindex="-1">Afriat 把公理收成线性不等式 <a class="header-anchor" href="#afriat-把公理收成线性不等式" aria-label="Permalink to &quot;Afriat 把公理收成线性不等式&quot;">​</a></h3><p>Afriat（1967）：GARP 成立当且仅当存在数 \\(u^t\\)、\\(\\lambda^t\\gt 0\\) 使</p> \\[u^s\\le u^t+\\lambda^t p^t\\cdot(x^s-x^t). \\]<p>这些数是一个凹的分段线性效用在观测点上的值与梯度。通过则样本可被理性化；失败则不存在局部非饱和的连续凹偏好能生成这批选择。</p><p><span class="marginnote">WARP 是两期图上的筛；GARP 是多期链上的筛。光滑极限里，GARP 对应斯勒茨基对称加负半定的离散版，WARP 只对应负半定的成对版。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先构造显示偏好图：节点是观测束，有向边是 \\(R^D\\)。检查是否存在严格更便宜的循环（GARP）或任何循环（SARP，单值时）。通过则解 Afriat 不等式，得到样本上精确、样本外以凹包络延拓的 \\(u\\)。这是非参数需求的可操作核，Varian 1982 把它写成可计算的检验。</p><p>本课不把 Hurwicz–Uzawa 的光滑可积再推一遍。那是<a href="/econ/integrability">可积性与恢复偏好</a>在函数 \\(x(p,w)\\) 上的缺口。这里对象是有限 \\((p^t,w^t,x^t)\\)。WARP 过而 GARP 不过，说明成对干净、链上有环——不能已经宣称「恢复了效用」。</p>',16)),(E(),o(p,null,{default:A(()=>[n(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20WARP%5B%22WARP%EF%BC%9A%E6%88%90%E5%AF%B9%E4%B8%8D%E5%BE%AA%E7%8E%AF%22%5D%20--%3E%20CHAIN%5B%22%E4%BC%A0%E9%80%92%E9%97%AD%E5%8C%85%20R%22%5D%0A%20%20CHAIN%20--%3E%20SARP%5B%22SARP%EF%BC%9A%E9%93%BE%E6%97%A0%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20CHAIN%20--%3E%20GARP%5B%22GARP%EF%BC%9A%E6%97%A0%E4%B8%A5%E6%A0%BC%E6%9B%B4%E4%BE%BF%E5%AE%9C%E7%9A%84%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20GARP%20--%3E%20AF%5B%22Afriat%20%E4%B8%8D%E7%AD%89%E5%BC%8F%22%5D%0A%20%20AF%20--%3E%20U%5B%22%E5%87%B9%E5%88%86%E6%AE%B5%E7%BA%BF%E6%80%A7%E6%95%88%E7%94%A8%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"单值需求下 SARP 与「严格凸理性化」接近；集值、无差异平台要用 GARP。家庭数据常有平段，检验默认走 GARP。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"GARP 把第一课的「最大元不循环」改写成数据语句。无需指定 Cobb–Douglas 或拟线性，也无需可微。失败则这批预算选择容不下凹理性偏好——不是某个弹性的符号估错。通过只表示尚未被拒绝：观测稀疏时公理很少咬合，效力随预算交叉密度上升。",-1)),(E(),o(p,null,{default:A(()=>[n(r,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20O1%5B%22%E8%A7%82%E6%B5%8B%201%EF%BC%9A%E9%80%89%20x1%EF%BC%8Cx2%20%E4%B9%9F%E4%B9%B0%E5%BE%97%E8%B5%B7%22%5D%20--%3E%20E1%5B%22x1%20%E5%81%8F%E5%A5%BD%E4%BA%8E%20x2%22%5D%0A%20%20O2%5B%22%E8%A7%82%E6%B5%8B%202%EF%BC%9A%E9%80%89%20x2%EF%BC%8Cx3%20%E4%B9%9F%E4%B9%B0%E5%BE%97%E8%B5%B7%22%5D%20--%3E%20E2%5B%22x2%20%E5%81%8F%E5%A5%BD%E4%BA%8E%20x3%22%5D%0A%20%20O3%5B%22%E8%A7%82%E6%B5%8B%203%EF%BC%9A%E9%80%89%20x3%EF%BC%8Cx1%20%E4%B9%9F%E4%B9%B0%E5%BE%97%E8%B5%B7%22%5D%20--%3E%20E3%5B%22x3%20%E5%81%8F%E5%A5%BD%E4%BA%8E%20x1%22%5D%0A%20%20E1%20--%3E%20LOOP%5B%22%E4%BC%A0%E9%80%92%E9%97%AD%E5%8C%85%E6%88%90%E7%8E%AF%EF%BC%9Ax1%E2%86%92x2%E2%86%92x3%E2%86%92x1%22%5D%0A%20%20E2%20--%3E%20LOOP%0A%20%20E3%20--%3E%20LOOP%0A%20%20LOOP%20--%3E%20FAIL%5B%22WARP%20%E6%88%90%E5%AF%B9%E5%85%A8%E8%BF%87%EF%BC%8CGARP%20%E5%88%A4%E7%8E%AF%EF%BC%9A%E4%B8%8D%E5%AD%98%E5%9C%A8%E7%90%86%E6%80%A7%E5%8C%96%22%5D%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>与 WARP 的分工：成对筛便宜、可画图；链筛才对应存在性。Afriat 数不唯一，与序数效用同一警告。恢复成功不是测出了幸福，是存在某一 \\(u\\) 嵌得进去。</p><p><span class="marginnote">聚合需求不必满足 GARP。个人通过、市场失败，只说明加总不是一个消费者。不要把个人公理写到市场上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>测量误差、口味漂移、家庭内部谈判，都会表现为 GARP 失败，不一定是「个人不理性」。本栏主干仍用理性作工作假说；检验失败先问对象是否切错。不可分商品、离散选择，Afriat 的凹连续版本过强，要另写整数版本。</p><p>也不要把 GARP 读成均衡或社会福利。这里没有市场出清，只有一个决策者的预算表。光滑可积、期望效用，都是后课另加的结构：确定消费上的 Afriat \\(u\\) 不能直接拿去对彩票取期望。</p><p><span class="marginnote">常见误区：GARP 通过不等于「测出了消费者的效用」，更不是幸福度评分。它只说这批观测还没被拒绝、存在某个凹效用嵌得进去；观测稀疏时公理几乎不咬合，数据越密检验力才越强。Afriat 求出的数也不唯一，与序数效用的警告相同。</span></p><p>后课默认：从有限选择恢复偏好，检验 GARP、解 Afriat；完整函数上的恢复，交给可积性课的 \\(S\\) 对称。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WARP 管成对；SARP / GARP 管链。循环一致性在这里才闭合。</li><li>GARP 允许集值无差异；SARP 更贴单值需求。</li><li>Afriat 1967：GARP 等价于凹分段线性效用的存在。</li><li>通过尚未证实「真实 \\(u\\)」，只表示模型未被这批数据拒绝。</li><li>出处：Afriat, 1967；Varian, <em>Econometrica</em>, 1982；Houthakker 的 SARP 传统。</li></ul>',9))])}const C=s(P,[["render",R]]);export{u as __pageData,C as default};
